import sys

MOD = 998244353

def fast_exponentiation(base, exponent):
    result = 1
    b = base % MOD
    e = exponent
    while e > 0:
        if e & 1:
            result = (result * b) % MOD
        b = (b * b) % MOD
        e >>= 1
    return result

def reciprocal_two():
    return fast_exponentiation(2, MOD - 2)

def main():
    input_line = sys.stdin.readline().strip()
    tokens = input_line.split()
    n = int(tokens[0])
    m = int(tokens[1])
    l = int(tokens[2])
    r = int(tokens[3])
    length = r - l + 1
    if n % 2 != 0 and m % 2 != 0:
        print(fast_exponentiation(length, n * m))
    else:
        base = fast_exponentiation(length, n * m - 1)
        if length % 2 == 0:
            res = (base * (length // 2)) % MOD
        else:
            res = ((base * ((length + 1) // 2)) % MOD + MOD - ((base + MOD - 1) % MOD * reciprocal_two()) % MOD) % MOD
        print(res)

